-- Replace the clinic service catalog with the four registration, checkout, procedure, and investigation lists.

ALTER TABLE medical_services DROP CONSTRAINT IF EXISTS medical_services_type_check;

UPDATE medical_services
SET service_type = CASE service_type
  WHEN 'Administrative & Coordination Services' THEN 'Administrative, Coordination and Other Services'
  WHEN 'Others' THEN 'Administrative, Coordination and Other Services'
  WHEN 'Medical Procedures Services' THEN 'Procedures & Interventions Services'
  WHEN 'Surgical Procedures Services' THEN 'Procedures & Interventions Services'
  ELSE service_type
END;

ALTER TABLE medical_services
  ADD COLUMN unit_price_egp numeric(12, 2),
  ADD COLUMN unit_price_eur numeric(12, 2);
ALTER TABLE medical_services
  ADD CONSTRAINT medical_services_unit_price_egp_check CHECK (unit_price_egp IS NULL OR unit_price_egp >= 0),
  ADD CONSTRAINT medical_services_unit_price_eur_check CHECK (unit_price_eur IS NULL OR unit_price_eur >= 0);
UPDATE medical_services SET unit_price_eur = price WHERE unit_price_eur IS NULL;

ALTER TABLE medical_services
  ADD CONSTRAINT medical_services_type_check
  CHECK (service_type IN (
    'Professional Services',
    'Administrative, Coordination and Other Services',
    'Procedures & Interventions Services',
    'Investigations [Laboratory & Imaging] Services'
  ));

DELETE FROM medication_route_services;

UPDATE medical_services SET deleted_at = now() WHERE deleted_at IS NULL;


SELECT mr.id, s.id
FROM medication_routes mr
JOIN medical_services s ON s.deleted_at IS NULL
  AND s.code = CASE mr.route
    WHEN 'IV Injection' THEN 'YRN-MP-002'
    WHEN 'IM injection' THEN 'YRN-MP-003'
    WHEN 'IV Infusion / Drip' THEN 'YRN-MP-004'
    WHEN 'SC injection' THEN 'YRN-MP-005'
  END
WHERE mr.route IN ('IV Injection', 'IM injection', 'IV Infusion / Drip', 'SC injection');
